import{c as s,$ as l,Q as r,j as n,g as a,o,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"Настройки пространства","description":"Управление ставкой мастера, наценкой, распределением накладных расходов, паспортом мастерской и архивацией рабочих пространств в ОмниКрафт ЕРП.","frontmatter":{"title":"Настройки пространства","description":"Управление ставкой мастера, наценкой, распределением накладных расходов, паспортом мастерской и архивацией рабочих пространств в ОмниКрафт ЕРП.","datePublished":"2026-08-20","dateModified":"2026-11-15","order":7},"headers":[],"relativePath":"ru/docs/resources/space-settings.md","filePath":"ru/docs/resources/space-settings.md","lastUpdated":1794700800000}'),g={name:"ru/docs/resources/space-settings.md"},h={id:"настроики-пространства",tabindex:"-1"};function c(p,t,m,u,f,x){const e=l("DocIcon");return r(),n("div",null,[a("h1",h,[o(e,{name:"settings"}),t[0]||(t[0]=i(" Настройки пространства ",-1)),t[1]||(t[1]=a("a",{class:"header-anchor",href:"#настроики-пространства","aria-label":'Permalink to "Настройки пространства"'},"​",-1))]),t[2]||(t[2]=d('<p>Вкладка <strong>«Настройки»</strong> служит экономическим фундаментом вашего текущего дела. Здесь задаются базовые нормативы рентабельности — стоимость рабочего времени, плановая наценка и правила распределения косвенных расходов. Программа автоматически подставляет эти нормативы в расчеты изделий и услуг, избавляя от рутины и защищая от кассовых разрывов.</p><p>В <strong>ОмниКрафт ЕРП</strong> настройки строго изолированы для каждого рабочего пространства. Если Вы развиваете несколько независимых направлений в тарифе ПРО (например, кожевенную мастерскую, студию сервисного ремонта и розничный магазин), у каждого из них действует персональная ставка труда, собственный набор накладных расходов и изолированная база данных.</p><hr><h2 id="экономические-нормативы-рентабельности" tabindex="-1">Экономические нормативы рентабельности <a class="header-anchor" href="#экономические-нормативы-рентабельности" aria-label="Permalink to &quot;Экономические нормативы рентабельности&quot;">​</a></h2><p>В основном окне вкладки расположены две ключевые карточки управления экономикой: <strong>«Базовые параметры ценообразования»</strong> и <strong>«Накладные расходы»</strong>.</p><h3 id="_1-системная-ставка-мастера-руб-час" tabindex="-1">1. Системная ставка мастера (руб./час) <a class="header-anchor" href="#_1-системная-ставка-мастера-руб-час" aria-label="Permalink to &quot;1. Системная ставка мастера (руб./час)&quot;">​</a></h3><p>Это минимальная расчетная стоимость одного часа Вашего квалифицированного труда либо рабочего времени наемного мастера.</p><ul><li><strong>Как работает в системе:</strong> При создании технологической карты изделия или заказ-наряда программа умножает заложенную норму времени на эту ставку. Например, если на изготовление портмоне заложено 2,5 часа нормы при ставке 800 рублей в час, программа включит 2 000 рублей в себестоимость по статье «Стоимость работы».</li><li><strong>Зачем корректировать:</strong> Ставка обязана отражать реальный уровень квалификации, техническую оснащенность мастерской и рыночные условия. Регулярная индексация ставки гарантирует, что рост вашего мастерства прямо конвертируется в доход, а не обесценивается инфляцией.</li><li><strong>Где применяется:</strong> В расчетах калькулятора изделий, при выпуске партий на верстаке и при формировании смет сервисных заказ-нарядов.</li></ul><hr><h3 id="_2-глобальная-торговая-наценка" tabindex="-1">2. Глобальная торговая наценка (%) <a class="header-anchor" href="#_2-глобальная-торговая-наценка" aria-label="Permalink to &quot;2. Глобальная торговая наценка (%)&quot;">​</a></h3><p>Плановый процент коммерческой прибыли, который программа начисляет поверх <strong>полной себестоимости</strong> (материалы + трудозатраты + накладные расходы) при формировании рекомендованной розничной цены.</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Ценообразование</span><div class="formula-heading">Формула рекомендованной розничной цены</div></div><div class="formula-equation-box"><div class="math-line"><span class="math-var">Розничная цена</span><span class="math-op">=</span><span class="math-calc-expr">Полная себестоимость</span><span class="math-op">×</span><span class="math-calc-expr"> (1 + <span class="math-fraction"><span class="math-numerator"><span class="math-var">Наценка</span></span><span class="math-denominator">100</span></span> ) </span></div></div><div class="formula-card-bottom"><p>Полная себестоимость включает расход сырья, оплату нормо-часов мастера и долю общецеховых накладных расходов.</p></div></div><ul><li><strong>Гибкость на практике:</strong> Значение наценки служит системным ориентиром по умолчанию. В карточке любого конкретного товара или услуги вы вправе скорректировать итоговую розничную цену вручную (например, для праздничной распродажи или штучного коллекционного изделия).</li><li><strong>Экономический смысл:</strong> Наценка формирует подушку безопасности вашего бизнеса. Она покрывает неизбежные технологические риски, брак сырья, сезонные спады потребительского спроса и бюджет на рекламу.</li></ul><hr><h3 id="_3-накладные-расходы-косвенные-затраты-бизнеса" tabindex="-1">3. Накладные расходы (Косвенные затраты бизнеса) <a class="header-anchor" href="#_3-накладные-расходы-косвенные-затраты-бизнеса" aria-label="Permalink to &quot;3. Накладные расходы (Косвенные затраты бизнеса)&quot;">​</a></h3><p>Дело мастера складывается не только из видимого сырья и часов работы. Аренда помещения, отопление и электричество, налоги, упаковочные материалы, амортизация оборудования, подписка на сервисы и комиссия эквайринга требуют регулярных выплат.</p><p>В <strong>ОмниКрафт ЕРП</strong> Вы создаете персональный реестр статей накладных расходов, которые <strong>автоматически включаются в калькуляцию каждого изделия</strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Тип норматива</th><th style="text-align:left;">Принцип расчета</th><th style="text-align:left;">Для каких затрат применяется</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Процентный норматив (%)</strong></td><td style="text-align:left;">Доля от стоимости материалов или базовой себестоимости</td><td style="text-align:left;">Банковский эквайринг, комиссии торговых площадок, транспортная логистика, расходники упаковки</td></tr><tr><td style="text-align:left;"><strong>Фиксированная сумма (руб.)</strong></td><td style="text-align:left;">Твердая сумма, добавляемая к каждой выпущенной единице</td><td style="text-align:left;">Постоянная аренда мастерской (в пересчете на плановый выпуск), фирменные бирки, сертификаты, упаковка</td></tr></tbody></table><h4 id="управление-статьями-затрат" tabindex="-1">Управление статьями затрат <a class="header-anchor" href="#управление-статьями-затрат" aria-label="Permalink to &quot;Управление статьями затрат&quot;">​</a></h4><ul><li><strong>Добавление:</strong> Нажмите кнопку <strong>«Добавить статью»</strong>, укажите понятное наименование (например, <em>«Аренда мастерской»</em> или <em>«Фирменная коробка»</em>), выберите тип норматива (процент или твердая сумма) и введите значение. Статья сразу появится в реестре.</li><li><strong>Редактирование и удаление:</strong> Вы можете скорректировать норматив или удалить потерявшую актуальность статью через кнопки действия в строке.</li></ul><div class="warning custom-block"><p class="custom-block-title">Неизменность исторической отчетности</p><p>Изменение или удаление статьи накладных расходов <strong>не пересчитывает задним числом уже закрытые продажи и архивные партии</strong>. Новые нормативы вступают в силу исключительно для последующих расчетов. Это защищает бухгалтерский баланс и журнал движения денег от искажения прошлой отчетности.</p></div><hr><h3 id="_4-избирательное-отображение-полеи-выбора-дат" tabindex="-1">4. Избирательное отображение полей выбора дат <a class="header-anchor" href="#_4-избирательное-отображение-полеи-выбора-дат" aria-label="Permalink to &quot;4. Избирательное отображение полей выбора дат&quot;">​</a></h3><p>По умолчанию во всех оперативных формах программы поля ручного ввода дат скрыты для максимального ускорения работы: система автоматически подставляет текущее число.</p><p>Если Вам регулярно требуется оформлять поступления материалов прошедшей датой, вносить ретроспективные кассовые ордера или планировать будущие отгрузки:</p><ol><li>Разверните блок <strong>«Настройка полей ввода дат»</strong>;</li><li>Отметьте нужные разделы галочками (Склад, ДДС, Продажи, Заказ-наряды);</li><li>Нажмите <strong>«Сохранить настройки»</strong>.</li></ol><hr><h2 id="паспорт-рабочего-пространства-управление-профилем" tabindex="-1">Паспорт рабочего пространства: Управление профилем <a class="header-anchor" href="#паспорт-рабочего-пространства-управление-профилем" aria-label="Permalink to &quot;Паспорт рабочего пространства: Управление профилем&quot;">​</a></h2><p>Карточка самого рабочего пространства настраивается через боковую выдвижную панель (меню выбора пространств в левом верхнем углу интерфейса):</p><ul><li><strong>Пользовательское наименование:</strong> Присвойте пространству емкое имя (<em>«Северная Мануфактура»</em>, <em>«Ремонт оптики»</em>, <em>«Гончарный цех»</em>). Название выводится в заголовке окна программы и на печатных документах.</li><li><strong>Описание и специализация:</strong> Зафиксируйте назначение площадки и внутренние правила мастерской.</li><li><strong>Отраслевой профиль:</strong> Выберите ведущее направление — «Производство и ремесло», «Услуги и сервис» либо «Торговля». Программа автоматически оптимизирует состав вкладок и терминологию под выбранный профиль.</li></ul><hr><h2 id="жизненныи-цикл-пространства-и-архивация" tabindex="-1">Жизненный цикл пространства и архивация <a class="header-anchor" href="#жизненныи-цикл-пространства-и-архивация" aria-label="Permalink to &quot;Жизненный цикл пространства и архивация&quot;">​</a></h2><p>В программе реализован бережный регламент управления проектами, исключающий случайную потерю производственной истории:</p><ol><li><strong>Правило одного активного пространства в базовой лицензии:</strong> Стандартный режим спроектирован для максимальной концентрации на одном основном деле. Если Вы завершаете проект или берете паузу, текущее пространство отправляется в архив, освобождая место для нового направления.</li><li><strong>Архивация вместо физического удаления:</strong> При отправке пространства в архив все данные (остатки сырья, себестоимость оборудования, кассовые проводки ДДС, готовая продукция и клиентская база) полностью консервируются. Ни одна запись не удаляется.</li><li><strong>Льготный период безопасной отмены (льготный период):</strong> После архивации система предоставляет льготный интервал времени. Если действие совершено случайно, Вы можете мгновенно вернуть пространство в рабочий статус одним действием без дополнительных условий.</li><li><strong>Параллельная работа в лицензии ПРО:</strong> Тариф ПРО снимает ограничение на число активных направлений. Вы можете одновременно держать открытыми десятки мастерских и переключаться между ними за секунду.</li><li><strong>Окончательное удаление:</strong> Полное стирание базы данных доступно только из архивного списка и сопровождается строгим предупреждением. Программа требует явного подтверждения, защищая от случайных кликов.</li></ol><hr><h2 id="инженерная-точность-и-сохранность-данных" tabindex="-1">Инженерная точность и сохранность данных <a class="header-anchor" href="#инженерная-точность-и-сохранность-данных" aria-label="Permalink to &quot;Инженерная точность и сохранность данных&quot;">​</a></h2><p>Вся учетная механика пространства подчинена жестким правилам надежности:</p><ul><li><strong>Изоляция файлов данных:</strong> Каждое пространство хранится в отдельной локальной базе данных SQLite (<code>workspace_&lt;id&gt;.db</code>). Сбой или архивация одного проекта технически не способны повредить данные соседних мастерских.</li><li><strong>Целочисленное масштабирование денежных сумм:</strong> Все ставки, наценки и коэффициенты расходов хранятся в базе данных как целые числа с четырехзначным масштабированием (умножение на 10 000). Это исключает ошибки вычислений с плавающей точкой, потерю копеек и накопление погрешностей при длительном ведении учета.</li><li><strong>Регламент локальных резервных копий:</strong> Рекомендуется периодически сохранять резервную копию рабочей базы на внешний накопитель перед масштабными пересмотрами нормативов или сменой состава оборудования.</li></ul><hr><h2 id="сводная-матрица-влияния-нормативов-на-бизнес" tabindex="-1">Сводная матрица влияния нормативов на бизнес <a class="header-anchor" href="#сводная-матрица-влияния-нормативов-на-бизнес" aria-label="Permalink to &quot;Сводная матрица влияния нормативов на бизнес&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Параметр настройки</th><th style="text-align:left;">Точка применения в программе</th><th style="text-align:left;">Риск при занижении</th><th style="text-align:left;">Риск при завышении</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Ставка мастера</strong></td><td style="text-align:left;">Себестоимость труда в калькуляторе и нарядах</td><td style="text-align:left;">Обесценивание собственного времени, мнимая рентабельность</td><td style="text-align:left;">Завышение отпускной цены выше рыночного спроса</td></tr><tr><td style="text-align:left;"><strong>Накладные расходы</strong></td><td style="text-align:left;">Полная себестоимость единицы продукции</td><td style="text-align:left;">Кассовые разрывы: прибыль «на бумаге» съедается арендой и налогами</td><td style="text-align:left;">Отказ от выгодных типовых заказов из-за завышенного порога</td></tr><tr><td style="text-align:left;"><strong>Торговая наценка</strong></td><td style="text-align:left;">Рекомендованная розничная цена в каталоге</td><td style="text-align:left;">Отсутствие средств на развитие мастерской и маркетинг</td><td style="text-align:left;">Снижение конверсии в розничные продажи и долгий цикл сделки</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Регламент пересмотра нормативов</p><p>Не меняйте экономические параметры пространства слишком часто. Хаотичные еженедельные колебания ставки искажают сравнительную аналитику рентабельности. Оптимальный цеховой ритм — пересмотр нормативов <strong>один раз в квартал</strong> либо при фундаментальных изменениях (переезд в новое помещение, закупка производительного оборудования, резкий скачок цен поставщиков).</p></div>',42))])}const _=s(g,[["render",c]]);export{y as __pageData,_ as default};
